java 复制代码 @Bean public MessageConverter messageConverter () { return new Jackson2JsonMessageConverter (); }
java 复制代码 // 发送 Map 对象（自动转 JSON） Map < String , Object > msg = new HashMap <> (); msg . put ( "name" , "张三" ); msg . put ( "age" , 18 ); rabbitTemplate . convertAndSend ( "object.queue" , msg ); // 接收自动反序列化 @RabbitListener ( queues = "object.queue" ) public void listenObjectQueue ( Map < String , Object > msg ) { System . out . println ( msg ); }

问题 ：消息可能因网络问题被重复投递，消费者需保证 同一消息处理多次结果相同 。
方案一：唯一消息 ID
java 复制代码 // 发送时设置唯一 ID CorrelationData cd = new CorrelationData ( UUID . randomUUID (). toString ()); rabbitTemplate . convertAndSend ( "exchange" , "key" , msg , cd ); // 消费时检查 ID @RabbitListener ( queues = "queue" ) public void listen ( String msg , Message message ) { String msgId = message . getMessageProperties (). getMessageId (); // 查 Redis/DB，ID 已存在则跳过 if ( redisTemplate . opsForValue (). setIfAbsent ( "mq:msg:" + msgId , "1" , 1 , TimeUnit . DAYS )) { // 首次处理 doProcess ( msg ); } // 重复消息直接忽略 }
方案二：业务判断（更推荐）
java 复制代码 // 下单业务幂等性：先查订单状态，已处理则跳过 @RabbitListener ( queues = "pay.success.queue" ) public void handlePaySuccess ( Long orderId ) { Order order = orderService . getById ( orderId ); if ( order == null || order . getStatus () != OrderStatus . UNPAID ) { return ; // 已处理过，幂等跳过 } orderService . updateStatus ( orderId , OrderStatus . PAID ); }
💡 业务判断方案更可靠 ，不依赖消息 ID，推荐优先使用。

如果 value 自己手动转 JSON，直接用 StringRedisTemplate ，无需配置序列化：
java 复制代码 @Autowired private StringRedisTemplate stringRedisTemplate ; @Autowired private ObjectMapper objectMapper ; // 存对象 User user = new User ( "Jack" , 18 ); String json = objectMapper . writeValueAsString ( user ); stringRedisTemplate . opsForValue (). set ( "user:1" , json ); // 取对象 String val = stringRedisTemplate . opsForValue (). get ( "user:1" ); User u = objectMapper . readValue ( val , User . class );
💡 推荐 StringRedisTemplate + 手动 JSON 转换，更清晰可控。

 ( key , "" , 2 , TimeUnit . MINUTES ); return null ; } stringRedisTemplate . opsForValue (). set ( key , JSONUtil . toJsonStr ( shop ), 30 , TimeUnit . MINUTES ); } catch ( Exception e ) { throw new RuntimeException ( e ); } finally { unlock ( lockKey ); // 释放锁 } return shop ; } private boolean tryLock ( String key ) { Boolean flag = stringRedisTemplate . opsForValue (). setIfAbsent ( key , "1" , 10 , TimeUnit . SECONDS ); return BooleanUtil . isTrue ( flag ); } private void unlock ( String key ) { stringRedisTemplate . delete ( key ); }
方案二：逻辑过期（高可用性）
java 复制代码 // 存入时带逻辑过期时间（key 本身不设 TTL） public void setWithLogicalExpire ( String key , Object value , Long time , TimeUnit unit ) { RedisData redisData = new RedisData (); redisData . setData ( value ); redisData . setExpireTime ( LocalDateTime . now (). plusSeconds ( unit . toSeconds ( time ))); stringRedisTemplate . opsForValue (). set ( key , JSONUtil . toJsonStr ( redisData )); } // 查询时判断逻辑过期 private static final ExecutorService REBUILD_EXECUTOR = Executors . newFixedThreadPool ( 10 ); public Shop queryWithLogicalExpire ( Long id ) { String key = "cache:shop:" + id ; String json = stringRedisTemplate . opsForValue (). get ( key ); if ( StrUtil . isBlank ( json )) return null ; RedisData redisData = JSONUtil . toBean ( json , RedisData . class ); Shop shop = JSONUtil . toBean (( JSONObject ) redisData . getData (), Shop . class ); if ( redisData . getExpireTime (). isAfter ( LocalDateTime . now ())) { return shop ; // 未过期，直接返回 } // 已过期，尝试异步重建 String lockKey = "lock:shop:" + id ; if ( tryLock ( lockKey )) { REBUILD_EXECUTOR . submit (() -> { try { Shop newShop = shopMapper . selectById ( id ); setWithLogicalExpire ( key , newShop , 30L , TimeUnit . MINUTES ); } finally { unlock ( lockKey ); } }); } return shop ; // 返回旧数

