方式一：@RefreshScope
java 复制代码 @RestController @RequestMapping ( "/user" ) @RefreshScope // 加这个注解 public class UserController { @Value ( "${pattern.dateformat}" ) private String dateformat ; @GetMapping ( "/now" ) public String now () { return LocalDateTime . now (). format ( DateTimeFormatter . ofPattern ( dateformat )); } }
方式二：@ConfigurationProperties（推荐）
java 复制代码 @Component @ConfigurationProperties ( prefix = "pattern" ) // 自动热更新，无需 @RefreshScope @Data public class PatternProperties { private String dateformat ; private String envSharedValue ; }

json 复制代码 { "query" : { "bool" : { "must" : [ { "match" : { "all" : "如家" } } ], // 必须匹配（参与算分） "should" : [ { "term" : { "starName" : "五" } } ], // 可选匹配（加分） "must_not" : [ { "range" : { "price" : { "gt" : 500 } } } ], // 必须不匹配（过滤，不算分） "filter" : [ { "range" : { "score" : { "gte" : 45 } } } ] // 过滤（不算分，性能好） } } }
子句 是否算分 含义 must ✅ 必须匹配 should ✅ 满足即加分（无 must 时至少满足一个） must_not ❌ 必须不匹配（过滤） filter ❌ 必须匹配（过滤，性能好）
💡 相关性算分 ：must 和 should 参与打分；filter 和 must_not 仅过滤，性能更好。

sql 复制代码 CREATE TABLE 表名 ( 字段名 数据类型 [ 约束 ], 字段名 数据类型 [ 约束 ], ... ) COMMENT '表注释' ;
示例：创建用户表 ：
sql 复制代码 CREATE TABLE user ( id BIGINT PRIMARY KEY AUTO_INCREMENT COMMENT '主键ID' , username VARCHAR ( 50 ) NOT NULL UNIQUE COMMENT '用户名' , password VARCHAR ( 200 ) NOT NULL COMMENT '密码' , nickname VARCHAR ( 100 ) COMMENT '昵称' , phone CHAR ( 11 ) COMMENT '手机号' , email VARCHAR ( 100 ) COMMENT '邮箱' , gender TINYINT DEFAULT 1 COMMENT '性别：1男2女' , avatar VARCHAR ( 500 ) COMMENT '头像URL' , balance DECIMAL ( 10 , 2 ) DEFAULT 0 COMMENT '余额' , status TINYINT DEFAULT 1 COMMENT '状态：1正常0禁用' , create_time DATETIME DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间' , update_time DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间' ) COMMENT '用户表' ;
各约束说明 ：
约束 说明 PRIMARY KEY 主键，唯一且非空 AUTO_INCREMENT 自动递增（配合整数主键） NOT NULL 非空约束 UNIQUE 唯一约束 DEFAULT 值 默认值 COMMENT '注释' 字段注释
⚠ 生产规范 ： 主键必须命名为 id ，类型 BIGINT AUTO_INCREMENT 必须有 create_time 和 update_time 字段 每个字段必须有 COMMENT 注释 表名、字段名用小写 + 下划线（snake_case）

text 复制代码 ERROR 1048 (23000): Column 'name' cannot be null
原因 ：向 NOT NULL 的列插入了 NULL 值
sql 复制代码 -- 错误 INSERT INTO users ( name , email ) VALUES ( NULL , 'test@test.com' ); -- name 是 NOT NULL -- 解决：给 name 赋值 INSERT INTO users ( name , email ) VALUES ( '默认名称' , 'test@test.com' );

GROUP BY 把相同值的行归为一组，再对每组进行聚合计算
sql 复制代码 -- 语法 SELECT 分组列 , 聚合函数 FROM 表名 GROUP BY 分组列 ;
sql 复制代码 -- 示例1：按部门统计人数 SELECT department AS 部门 , -- 分组依据列 COUNT ( * ) AS 人数 -- 对每个分组统计行数 FROM employees GROUP BY department ; -- 按部门分组 -- 结果：每个部门一行，显示部门名和人数 -- 示例2：按部门统计工资情况 SELECT department AS 部门 , COUNT ( * ) AS 人数 , SUM ( salary ) AS 工资总额 , ROUND ( AVG ( salary ), 2 ) AS 平均工资 , MAX ( salary ) AS 最高工资 , MIN ( salary ) AS 最低工资 FROM employees GROUP BY department ; -- 按部门分组，对每组分别计算 -- 示例3：按性别统计平均年龄 SELECT gender AS 性别 , COUNT ( * ) AS 人数 , AVG ( age ) AS 平均年龄 FROM employees GROUP BY gender ; -- 按性别分组 -- 示例4：按多列分组（按部门+城市统计） SELECT department AS 部门 , city AS 城市 , COUNT ( * ) AS 人数 FROM employees GROUP BY department , city ; -- 按部门和城市两列同时分组 -- 结果：每个（部门+城市）组合一行 -- ⚠️ 重要规则： -- SELECT 中出现的列，要么在 GROUP BY 中，要么是聚合函数！ -- 错误示例： -- SELECT name, department, COUNT(*) FROM employees GROUP BY department; -- name 没有在 GROUP BY 中，也不是聚合函数，MySQL 会报错（严格模式下）

HAVING 是对 GROUP BY 分组后的结果进行过滤（相当于对分组结果的 WHERE）
sql 复制代码 -- 语法 SELECT 分组列 , 聚合函数 FROM 表名 GROUP BY 分组列 HAVING 聚合函数条件 ;
sql 复制代码 -- 示例1：查询人数大于2的部门 SELECT department AS 部门 , COUNT ( * ) AS 人数 FROM employees GROUP BY department HAVING COUNT ( * ) > 2 ; -- 分组后，只保留人数>2的部门 -- 示例2：查询平均工资超过12000的部门 SELECT department AS 部门 , ROUND ( AVG ( salary ), 2 ) AS 平均工资 FROM employees GROUP BY department HAVING AVG ( salary ) > 12000 ; -- 只显示平均工资>12000的部门 -- 示例3：WHERE + GROUP BY + HAVING 同时使用 -- 查询：技术部和销售部中，人数超过2人的部门的平均工资 SELECT department AS 部门 , COUNT ( * ) AS 人数 , ROUND ( AVG ( salary ), 2 ) AS 平均工资 FROM employees WHERE department IN ( '技术部' , '销售部' ) -- ① 先过滤：只看技术部和销售部 GROUP BY department -- ② 按部门分组 HAVING COUNT ( * ) > 2 ; -- ③ 分组后，只保留人数>2的部门

级联操作决定：当 父表记录被删除或更新 时，子表的相关记录怎么处理。
级联选项 含义 RESTRICT 默认值，拒绝删除/更新父记录（如果有子记录） NO ACTION 和 RESTRICT 相同（MySQL 中等同） CASCADE 父记录删除/更新时，子记录 同步删除/更新 SET NULL 父记录删除/更新时，子表外键列 设为 NULL SET DEFAULT 子表外键设为默认值（MySQL InnoDB 不支持）
sql 复制代码 -- 示例1：CASCADE（级联删除和更新） CREATE TABLE dept2 ( dept_id INT PRIMARY KEY AUTO_INCREMENT , dept_name VARCHAR ( 50 ) NOT NULL ); CREATE TABLE emp2 ( emp_id INT PRIMARY KEY AUTO_INCREMENT , emp_name VARCHAR ( 50 ), dept_id INT , CONSTRAINT fk_emp2_dept2 FOREIGN KEY ( dept_id ) REFERENCES dept2 ( dept_id ) ON DELETE CASCADE -- 父删除 → 子自动删除 ON UPDATE CASCADE -- 父更新 → 子自动更新 );
sql 复制代码 -- 测试 CASCADE INSERT INTO dept2 ( dept_name ) VALUES ( '技术部' ); -- dept_id = 1 INSERT INTO emp2 ( emp_name , dept_id ) VALUES ( '张三' , 1 ); INSERT INTO emp2 ( emp_name , dept_id ) VALUES ( '李四' , 1 ); DELETE FROM dept2 WHERE dept_id = 1 ; -- 结果：dept2 中 dept_id=1 被删，emp2 中两条记录也自动删除 -- 示例2：SET NULL（级联置空） CREATE TABLE dept3 ( dept_id INT PRIMARY KEY AUTO_INCREMENT , dept_name VARCHAR ( 50 ) NOT NULL ); CREATE TABLE emp3 ( emp_id INT PRIMARY KEY AUTO_INCREMENT , emp_name VARCHAR ( 50 ), dept_id INT , -- 注意：SET NULL 要求此列允许 NULL CONSTRAINT fk_emp3_dept3 FOREIGN KEY ( dept_id ) REFERENCES dept3 ( dept_id ) ON DELETE SET NULL -- 父删除 → 子外键设为 NULL ON UPDATE SET NULL -- 父更新 → 子外键设为 NULL ); INSERT INTO dept3 ( dept_name ) VALUES ( '市场部' ); -- dept_id = 1 INSERT INTO emp3 ( emp_name , dept_id ) VALUES ( '王五' , 1 ); DELETE FROM dept3 WHERE dept_id = 1 ; -- 结果：emp3 中 dept_id 变为 NULL（员工还在，只是没有部门了） SELECT * FROM emp3 ;

text 复制代码 ERROR 1242 (21000): Subquery returns more than 1 row
原因：在需要单值的地方，子查询返回了多行
sql 复制代码 -- 错误：dept_name='技术部'只有一个，但如果有多个就会报错 SELECT * FROM emp WHERE dept_id = ( SELECT dept_id FROM dept WHERE dept_name LIKE '%部' ); -- 多个部门名含'部' -- 修复：用 IN 代替 = SELECT * FROM emp WHERE dept_id IN ( SELECT dept_id FROM dept WHERE dept_name LIKE '%部' );

一个事务读到了另一个事务"尚未提交"的数据。
图解：
text 复制代码 时间线：
事务A                           事务B
                                BEGIN;
                                UPDATE accounts SET balance=0 WHERE id=1;
                                -- 未提交！
BEGIN;
SELECT balance FROM accounts WHERE id=1;
-- 读到了 0（脏数据！）
                                ROLLBACK; -- B 回滚了，数据其实还是原来的值
-- 但 A 读到的是错误的 0
COMMIT;
危害： 读到了不真实的数据，可能基于错误数据做出错误决策。
类比： 你同事在草稿纸上写了一个未确认的方案给你看，你直接按草稿实施，结果同事后来删掉了草稿，说那是错误方案。

同一事务中，两次读取同一条数据，结果不一样（因为其他事务在期间修改并提交了）。
图解：
text 复制代码 时间线：
事务A                           事务B
BEGIN;
SELECT balance FROM accounts WHERE id=1;
-- 结果：1000
                                BEGIN;
                                UPDATE accounts SET balance=500 WHERE id=1;
                                COMMIT; -- B 提交了修改
SELECT balance FROM accounts WHERE id=1;
-- 结果：500（和第一次读的不一样！）
COMMIT;
危害： 同一事务内数据前后不一致，逻辑混乱。
与脏读的区别：
脏读：读到的是未提交的数据 不可重复读：读到的是已提交的数据，但同一事务内两次读结果不同
类比： 你上午查了一下银行余额是 1000 元，下午同一笔查询结果变成 500 元，因为你老婆中间取了 500 元。同一次查询，结果变了。

同一事务中，两次查询返回的行数不一样（因为其他事务在期间插入或删除了数据）。
图解：
text 复制代码 时间线：
事务A                           事务B
BEGIN;
SELECT * FROM orders WHERE user_id=1;
-- 返回 3 行
                                BEGIN;
                                INSERT INTO orders (user_id, amount) VALUES (1, 100);
                                COMMIT; -- B 插入了一行
SELECT * FROM orders WHERE user_id=1;
-- 返回 4 行（多了一行"幻影"数据！）
COMMIT;
危害： 同一事务内，查询出来的数据集不稳定，像"见鬼"一样多了行数据。
与不可重复读的区别：
不可重复读：同一行数据，两次读取 值 不同（UPDATE 导致） 幻读：同一条件查询，两次读取 行数 不同（INSERT/DELETE 导致）
类比：
不可重复读：你数钱，数了两次，第一次 100 张，第二次 50 张，张数变了（有人拿走了） 幻读：你数人头，数了两次，第一次 10 人，第二次 11 人，人数变了（有人悄悄进来了）

保证列中所有值都唯一，允许有 NULL（但只能有一个 NULL）。
sql 复制代码 -- 创建时添加唯一索引 CREATE TABLE users ( id INT PRIMARY KEY AUTO_INCREMENT , email VARCHAR ( 100 ) UNIQUE , -- 写法1：列定义时 phone VARCHAR ( 20 ), UNIQUE INDEX idx_phone ( phone ) -- 写法2：单独定义 ); -- 已有表，添加唯一索引 ALTER TABLE users ADD UNIQUE INDEX idx_email ( email );
使用场景： 邮箱、手机号、身份证号等需要唯一的字段。

最基本的索引类型，没有唯一性约束，单纯为了加速查询。
sql 复制代码 -- 创建时添加普通索引 CREATE TABLE articles ( id INT PRIMARY KEY AUTO_INCREMENT , title VARCHAR ( 200 ), author_id INT , created_at DATETIME , INDEX idx_author ( author_id ), -- 普通索引 INDEX idx_created ( created_at ) -- 时间索引 ); -- 已有表，添加普通索引 ALTER TABLE articles ADD INDEX idx_author ( author_id ); -- 或 CREATE INDEX idx_author ON articles ( author_id );
使用场景： 经常出现在 WHERE、JOIN、ORDER BY 子句中的字段。

在数据变更时 自动执行 的 SQL，可在 INSERT/UPDATE/DELETE 前后触发。
sql 复制代码 -- 场景：订单删除后，自动记录到历史表 DELIMITER // CREATE TRIGGER trg_order_delete AFTER DELETE ON ` order ` -- 在 order 表删除后触发 FOR EACH ROW -- 每行触发一次 BEGIN INSERT INTO order_history ( id , user_id , amount , delete_time ) VALUES ( OLD . id , OLD . user_id , OLD . amount , NOW ()); -- OLD 表示被删除的那行数据 END // DELIMITER ;
时机 操作 NEW / OLD BEFORE INSERT INSERT 前 NEW（新数据） AFTER INSERT INSERT 后 NEW（新数据） BEFORE UPDATE UPDATE 前 OLD/NEW AFTER UPDATE UPDATE 后 OLD/NEW BEFORE DELETE DELETE 前 OLD（旧数据） AFTER DELETE DELETE 后 OLD（旧数据）

sql 复制代码 EXPLAIN SELECT * FROM user WHERE username = 'Jack' ;
关键字段：
字段 说明 好/坏 type 访问类型 const/ref 好，ALL 坏（全表扫描） key 实际使用的索引 有 key 表示用了索引 rows 预估扫描行数 越小越好 Extra 额外信息 Using filesort / Using temporary 坏

只需继承 BaseMapper<T> ，立刻拥有所有 CRUD 方法 ！
java 复制代码 // 一行代码，18个现成方法 public interface UserMapper extends BaseMapper < User > { // 什么都不写，insert/delete/update/select 全有了 }
官方说法 ：MyBatis-Plus（简称 MP）是 MyBatis 的增强工具，在 MyBatis 基础上 只做增强不做改变 ，为简化开发、提高效率而生。

java 复制代码 // 查询：name = 'Jack' AND age >= 18 QueryWrapper < User > wrapper = new QueryWrapper < User > () . eq ( "username" , "Jack" ) // username = 'Jack' . ge ( "age" , 18 ) // age >= 18 . like ( "email" , "@qq.com" ) // email LIKE '%@qq.com%' . orderByDesc ( "create_time" ) // ORDER BY create_time DESC . last ( "LIMIT 10" ); // 拼接到 SQL 末尾 List < User > users = userMapper . selectList ( wrapper );
常用方法 ：
方法 SQL 含义 示例 eq("col", val) col = val 精确匹配 ne("col", val) col != val 不等于 gt/ge("col", val) col > / >= val 大于/大于等于 lt/le("col", val) col < / <= val 小于/小于等于 like("col", val) col LIKE %val% 模糊匹配 likeLeft/Right %val / val% 左/右模糊 between("col", a, b) col BETWEEN a AND b 区间 in("col", list) col IN (...) 包含 isNull/isNotNull col IS NULL / NOT NULL 空值 orderByAsc/Desc ORDER BY col ASC/DESC 排序 select("col1", "col2") SELECT col1, col2 指定查询字段

java 复制代码 // 用 Lambda 引用字段，编译时检查，不怕写错字段名 LambdaQueryWrapper < User > wrapper = new LambdaQueryWrapper < User > () . eq ( User :: getUsername , "Jack" ) // username = 'Jack' . ge ( User :: getAge , 18 ) // age >= 18 . like ( User :: getEmail , "@qq.com" ) // email LIKE '%@qq.com%' . orderByDesc ( User :: getCreateTime ); // ORDER BY create_time DESC List < User > users = userMapper . selectList ( wrapper );
条件构建（动态 SQL） ：
java 复制代码 String name = "Jack" ; // 可能是 null Integer age = null ; // 条件不传，不加入 SQL LambdaQueryWrapper < User > wrapper = new LambdaQueryWrapper < User > () // 第一个参数是 boolean：false 时不加这个条件 . eq ( name != null , User :: getUsername , name ) . ge ( age != null , User :: getAge , age );

首先，我们需要定义两个Caffeine的缓存对象，分别保存商品、库存的缓存数据。
在item-service的 com.heima.item.config 包下定义 CaffeineConfig 类：
java 复制代码 package com.heima.item.config ; import com.github.benmanes.caffeine.cache.Cache ; import com.github.benmanes.caffeine.cache.Caffeine ; import com.heima.item.pojo.Item ; import com.heima.item.pojo.ItemStock ; import org.springframework.context.annotation.Bean ; import org.springframework.context.annotation.Configuration ; @Configuration public class CaffeineConfig { @Bean public Cache < Long , Item > itemCache (){ return Caffeine . newBuilder () . initialCapacity ( 100 ) . maximumSize ( 10_000 ) . build (); } @Bean public Cache < Long , ItemStock > stockCache (){ return Caffeine . newBuilder () . initialCapacity ( 100 ) . maximumSize ( 10_000 ) . build (); } }
然后，修改item-service中的 com.heima.item.web 包下的ItemController类，添加缓存逻辑：
java 复制代码 @RestController @RequestMapping ( "item" ) public class ItemController { @Autowired private IItemService itemService ; @Autowired private IItemStockService stockService ; @Autowired private Cache < Long , Item > itemCache ; @Autowired private Cache < Long , ItemStock > stockCache ; // ...其它略 @GetMapping ( "/{id}" ) public Item findById ( @PathVariable ( "id" ) Long id ) { return itemCache . get ( id , key -> itemService . query () . ne ( "status" , 3 ). eq ( "id" , key ) . one () ); } @GetMapping ( "/stock/{id}" ) public ItemStock findStockById ( @PathVariable ( "id" ) Long id ) { return stockCache . get ( id , key -> stockService . getById ( key )); } }

