cpp 复制代码 // 基本语法 [ capture ]( params ) -> return_type { body } // 示例 auto add = []( int a , int b ) { return a + b ; }; cout << add ( 3 , 5 ); // 8 // 捕获 int x = 10 , y = 20 ; auto f1 = [ x , y ]() { return x + y ; }; // 值捕获 auto f2 = [ & x , & y ]() { x ++ ; y ++ ; }; // 引用捕获 auto f3 = [ = ]() { return x + y ; }; // 全部值捕获 auto f4 = [ & ]() { x ++ ; }; // 全部引用捕获 auto f5 = [ this ]() { /* 捕获 this */ }; // 捕获 this 指针 // 用于 STL std :: vector < int > v = { 3 , 1 , 4 , 1 , 5 }; std :: sort ( v . begin (), v . end (), []( int a , int b ) { return a > b ; });
💡 捕获规则 ： [] 不捕获 [=] 值捕获全部 [&] 引用捕获全部 [=, &x] 除 x 外全部值捕获 [&, x] 除 x 外全部引用捕获

vector 是 C++ 的 动态数组 ， 强烈推荐 替代 C 数组。
cpp 复制代码 #include <vector> // 创建 std :: vector < int > v1 ; // 空 vector std :: vector < int > v2 ( 5 ); // 5 个 0 std :: vector < int > v3 ( 5 , 10 ); // 5 个 10 std :: vector < int > v4 = { 1 , 2 , 3 , 4 , 5 }; // 初始化列表 std :: vector < int > v5 ( v4 ); // 拷贝构造 // 添加 v . push_back ( 6 ); // 末尾添加 v . emplace_back ( 7 ); // 原地构造（更高效） v . insert ( v . begin () + 2 , 99 ); // 指定位置插入 // 访问 v [ 0 ]; // 不检查越界 v . at ( 0 ); // 检查越界，抛异常 v . front (); // 首元素 v . back (); // 末元素 // 删除 v . pop_back (); // 删末尾 v . erase ( v . begin ()); // 删指定位置 v . erase ( v . begin (), v . begin () + 2 ); // 删区间 v . clear (); // 清空 // 大小 v . size (); // 元素个数 v . empty (); // 是否为空 v . capacity (); // 容量 v . shrink_to_fit (); // 缩容到 size // 遍历 for ( int x : v ) cout << x ; for ( auto it = v . begin (); it != v . end (); ++ it ) cout << * it ; for ( size_t i = 0 ; i < v . size (); i ++ ) cout << v [ i ];
💡 vector 扩容 ：通常 1.5 倍或 2 倍；扩容会重新分配内存 + 拷贝元素。

