java 复制代码 // 自定义类放进 HashSet 必须重写 equals 和 hashCode public class Student { String name ; int age ; @Override public int hashCode () { return Objects . hash ( name , age ); } @Override public boolean equals ( Object o ) { if ( this == o ) return true ; if ( o == null || getClass () != o . getClass ()) return false ; Student s = ( Student ) o ; return age == s . age && Objects . equals ( name , s . name ); } }

作用 ：默认 8KB 缓冲区，减少磁盘 IO 次数， 性能大幅提升 。
java 复制代码 public void bufferedCopy ( String src , String dst ) throws IOException { try ( BufferedInputStream bis = new BufferedInputStream ( new FileInputStream ( src )); BufferedOutputStream bos = new BufferedOutputStream ( new FileOutputStream ( dst ))) { byte [] buf = new byte [ 1024 ] ; int len ; while (( len = bis . read ( buf )) != - 1 ) { bos . write ( buf , 0 , len ); } } }
