class Solution {
public:
    int maxProfit(vector<int>& prices) {
        int low = INT_MAX;
        int result = 0;
        for (int i = 0; i < prices.size(); i++) {
            low = min(low, prices[i]);  // 取最左最⼩价格
            result = max(result, prices[i] - low); // 直接取最⼤区间利润
        }
        return result;
    }
};
