if (h > 0) sum += h; // 注意只有h⼤于零的时候，在统计到总和中
class Solution {
public:
    int trap(vector<int>& height) {
        int sum = 0;
        for (int i = 0; i < height.size(); i++) {
            // 第⼀个柱⼦和最后⼀个柱⼦不接⾬⽔
            if (i == 0 || i == height.size() - 1) continue;
            int rHeight = height[i]; // 记录右边柱⼦的最⾼⾼度
            int lHeight = height[i]; // 记录左边柱⼦的最⾼⾼度
            for (int r = i + 1; r < height.size(); r++) {
                if (height[r] > rHeight) rHeight = height[r];
            }
            for (int l = i - 1; l >= 0; l--) {
                if (height[l] > lHeight) lHeight = height[l];
            }
            int h = min(lHeight, rHeight) - height[i];
            if (h > 0) sum += h;
        }
        return sum;
    }
};

单调栈解法  
关于单调栈的理论基础，单调栈适合解决什么问题，单调栈的⼯作过程，⼤家可以先看这题讲解 739. 每⽇温度。
单调栈就是保持栈内元素有序。和栈与队列：单调队列⼀样，需要我们⾃⼰维持顺序，没有现成的容器可以⽤。
通常是⼀维数组，要寻找任⼀个元素的右边或者左边第⼀个⽐⾃⼰⼤或者⼩的元素的位置，此时我们就要想到可以
⽤单调栈了。
⽽接⾬⽔这道题⽬，我们正需要寻找⼀个元素，右边最⼤元素以及左边最⼤元素，来计算⾬⽔⾯积。
准备⼯作  
那么本题使⽤单调栈有如下⼏个问题：
1. ⾸先单调栈是按照⾏⽅向来计算⾬⽔，如图：
class Solution {
public:
    int trap(vector<int>& height) {
        if (height.size() <= 2) return 0;
        vector<int> maxLeft(height.size(), 0);
        vector<int> maxRight(height.size(), 0);
        int size = maxRight.size();
        // 记录每个柱⼦左边柱⼦最⼤⾼度
        maxLeft[0] = height[0];
        for (int i = 1; i < size; i++) {
            maxLeft[i] = max(height[i], maxLeft[i - 1]);
        }
        // 记录每个柱⼦右边柱⼦最⼤⾼度
        maxRight[size - 1] = height[size - 1];
        for (int i = size - 2; i >= 0; i--) {
            maxRight[i] = max(height[i], maxRight[i + 1]);
        }
        // 求和
        int sum = 0;
        for (int i = 0; i < size; i++) {
            int count = min(maxLeft[i], maxRight[i]) - height[i];
            if (count > 0) sum += count;
