        LinkedNode* tmp = cur->next;
        cur->next = cur->next->next;
        delete tmp;
        //delete命令指示释放了tmp指针原本所指的那部分内存，
        //被delete后的指针tmp的值（地址）并⾮就是NULL，⽽是随机值。也就是被delete后，
        //如果不再加上⼀句tmp=nullptr,tmp会成为乱指的野指针
        //如果之后的程序不⼩⼼使⽤了tmp，会指向难以预想的内存空间
        tmp=nullptr;
        _size--;
    }
    // 打印链表
