4. 快乐数  
⼒扣题⽬链接
编写⼀个算法来判断⼀个数 n 是不是快乐数。
「快乐数」定义为：对于⼀个正整数，每⼀次将该数替换为它每个位置上的数字的平⽅和，然后重复这个过程直到
这个数变为 1，也可能是 ⽆限循环 但始终变不到 1。如果 可以变为  1，那么这个数就是快乐数。
class Solution {
public:
    vector<int> intersection(vector<int>& nums1, vector<int>& nums2) {
        unordered_set<int> result_set; // 存放结果，之所以⽤set是为了给结果集去重
        int hash[1005] = {0}; // 默认数值为0
        for (int num : nums1) { // nums1中出现的字⺟在hash数组中做记录
            hash[num] = 1;
        }
        for (int num : nums2) { // nums2中出现话，result记录
            if (hash[num] == 1) {
                result_set.insert(num);
            }
        }
        return vector<int>(result_set.begin(), result_set.end());
    }
};

