if (count > result) result = count;
class Solution {
public:
    int maxSubArray(vector<int>& nums) {
        int result = INT32_MIN;
        int count = 0;
        for (int i = 0; i < nums.size(); i++) {
            count += nums[i];
            if (count > result) { // 取区间累计的最⼤值（相当于不断确定最⼤⼦序终⽌位置）
                result = count;
            }
            if (count <= 0) count = 0; // 相当于重置最⼤⼦序起始位置，因为遇到负数⼀定是拉低总和
        }
        return result;
    }
};

