需求一： 返回 n 个字符串拼接结果，如果没有传入字符串，返回空字符串 ""
java 复制代码 public class Demo02Var { public static void main ( String [] args ) { // 传入多个字符串, 拼接成一个大字符串 String result = concat ( "张无忌" , "张翠山" , "张三丰" , "张三" ); System . out . println ( "result = " + result ); // 输出: 张无忌张翠山张三丰张三 } public static String concat ( String ... s ) { // s 是可变参数, 本质是 String[] String str = "" ; // 定义结果字符串, 初始为空 for ( int i = 0 ; i < s . length ; i ++ ) { // 遍历所有字符串 str += s [ i ] ; // 每次拼接一个字符串 } return str ; // 返回拼接结果 } }
需求二： n 个字符串拼接，每个字符串之间用某字符分隔，没有传入返回 ""
java 复制代码 // 例: concat("-", "张三丰", "张翠山", "张无忌") -> 返回 "张三丰-张翠山-张无忌" public class Demo03Var { public static void main ( String [] args ) { String result = concat ( "-" , "张三丰" , "张翠山" , "张无忌" ); System . out . println ( "result = " + result ); // 输出: 张三丰-张翠山-张无忌 } // regex 是分隔符(普通参数), s 是可变参数, 放最后 public static String concat ( String regex , String ... s ) { String str = "" ; // 定义结果字符串 for ( int i = 0 ; i < s . length ; i ++ ) { // 遍历所有字符串 if ( i == s . length - 1 ) { // 最后一个元素 str += s [ i ] ; // 不加分隔符 } else { str += s [ i ] + regex ; // 非最后元素, 加分隔符 } } return str ; // 返回拼接结果 } }

概述： 数组对称索引位置上的元素互换。
比如 {1,2,3,4,5,6,7} 翻转后变成 {7,6,5,4,3,2,1} 。
java 复制代码 public class Demo01Reverse { public static void main ( String [] args ) { int [] arr = { 1 , 2 , 3 , 4 , 5 , 6 , 7 }; // 定义数组 // 双指针法: min 从头开始, max 从尾开始, 互换后向中间靠拢 for ( int min = 0 , max = arr . length - 1 ; min < max ; min ++ , max -- ) { // 交换 arr[min] 和 arr[max] int temp = arr [ min ] ; // 临时变量保存 arr[min] arr [ min ] = arr [ max ] ; // arr[min] 取 arr[max] 的值 arr [ max ] = temp ; // arr[max] 取 temp(原来的 arr[min]) } // 遍历打印翻转后的数组 for ( int i = 0 ; i < arr . length ; i ++ ) { System . out . print ( arr [ i ] + " " ); // 输出: 7 6 5 4 3 2 1 } } }

前提： 数组中的数据必须是 有序的 。
原理： 每次找中间索引对应的元素进行比较，每次查询少一半数据。
java 复制代码 public class Demo03Binary { public static void main ( String [] args ) { int [] arr = { 1 , 2 , 3 , 4 , 5 , 6 , 7 , 8 , 9 }; // 有序数组 int index = binary ( arr , 60 ); // 查找 60 System . out . println ( index ); // 输出: -1 (没找到) } public static int binary ( int [] arr , int data ) { // 定义三个变量, 分别代表最小索引、最大索引、中间索引 int min = 0 ; // 最小索引 int max = arr . length - 1 ; // 最大索引 int mid = 0 ; // 中间索引 while ( min <= max ) { // 只要范围有效就继续查 mid = ( min + max ) / 2 ; // 计算中间索引 if ( data > arr [ mid ] ) { // 要找的数据比中间值大 min = mid + 1 ; // 去右半边找, 更新 min } else if ( data < arr [ mid ] ) { // 要找的数据比中间值小 max = mid - 1 ; // 去左半边找, 更新 max } else { // 找到了 return mid ; // 返回索引 } } return - 1 ; // 没找到, 返回 -1 } }

