java 复制代码 public class Test01 { public static void main ( String [] args ) { //创建线程池对象 ExecutorService es = Executors . newFixedThreadPool ( 2 ); es . submit ( new MyRunnable ()); es . submit ( new MyRunnable ()); es . submit ( new MyRunnable ()); //es.shutdown();//关闭线程池对象 } }
