java 复制代码 public int hashCode () { int h = hash ; if ( h == 0 && ! hashIsZero ) { h = isLatin1 () ? StringLatin1 . hashCode ( value ) : StringUTF16 . hashCode ( value ); if ( h == 0 ) { hashIsZero = true ; } else { hash = h ; } } return h ; } ==================================================== StringLatin1 . hashCode ( value ) 底层源码 , String中的哈希算法 public static int hashCode ( byte [] value ) { int h = 0 ; for ( byte v : value ) { h = 31 * h + ( v & 0xff ); } return h ; }
java 复制代码 直接跑到StringLatin1 . hashCode ( value ) 底层源码 , 计算abc的哈希值 -> 0xff 这个十六进制对应的十进制255 任何数据和255做 & 运算 , 都是原值 第一圈 : h = 31 * 0 + 97 = 97 第二圈 : h = 31 * 97 + 98 = 3105 第三圈 : h = 31 * 3105 + 99 = 96354
